using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns menu button set by the bot for the given user; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.BotMenuButton> GetMenuButtonAsync(long userId = default)
    {

           using var activity =  StartCallActivity("GetMenuButtonAsync", typeof(GetMenuButton).FullName ?? "GetMenuButtonAsync");

           try
           {
             return client.GetMenuButtonAsync(userId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
